import{clockText as o}from"./score.min.js";export const CHEER_LINE="Not a leaf in sight. The lawn is spotless.";export function createCheer(){return{phase:"idle",t:0,armed:!1,done:!1}}export function resetCheer(e){return e.phase="idle",e.t=0,e.armed=!1,e.done=!1,e}export function isCheering(e){return e.phase==="cheer"}export function stepCheer(e,r,n,t){return e.phase==="cheer"?(e.t+=r>0?r:0,e.t>=t.seconds?(e.phase="idle",e.done=!0,"end"):null):n.free?n.spotless?e.armed&&!e.done?(e.phase="cheer",e.t=0,"start"):null:(e.armed=!0,null):null}export function skipCheer(e){return e.phase!=="cheer"?!1:(e.phase="idle",e.done=!0,!0)}export function cheerLift(e,r,n=!1){if(n||e<0||e>=r.hops*r.hopTime)return 0;const t=e%r.hopTime/r.hopTime;return r.hop*4*t*(1-t)}export function cheerSpin(e,r,n=!1){if(n)return 0;const t=Math.min(1,Math.max(0,(e-r.spin.from)/r.spin.time));return Math.PI*2*t*t*(3-2*t)}export function cheerOrbit(e,r,n=!1){if(n)return 0;const t=Math.min(1,Math.max(0,e/r.seconds));return r.orbit*Math.sin(Math.PI*t)}export function bannerFor(e,r=0,n=null){if(e!=="timed")return{big:"Spotless!",small:CHEER_LINE,extra:""};const t=Math.max(1,Math.round(r));let i="";return n===null?i="Your first clear!":t<n&&(i="A new best time!"),{big:"Lawn clear!",small:`in ${o(t)}`,extra:i}}export function cheerFocus(e,r){const n=(r.minX+r.maxX)/2,t=(r.minZ+r.maxZ)/2;return{x:(e.x+n)/2,z:(e.z+t)/2}}
